import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const u=JSON.parse('{"title":"杨梅竹斜街","description":"","frontmatter":{},"headers":[],"relativePath":"landmarks/yangmeizhu-xiejie.md","filePath":"landmarks/yangmeizhu-xiejie.md","lastUpdated":1787033866000}'),n={name:"landmarks/yangmeizhu-xiejie.md"};function o(d,t,i,s,h,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="杨梅竹斜街" tabindex="-1">杨梅竹斜街 <a class="header-anchor" href="#杨梅竹斜街" aria-label="Permalink to &quot;杨梅竹斜街&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1519501025264-65ba15a82390?w=1200" alt="杨梅竹斜街"></p><blockquote><p>&quot;一条斜街，半部民国书业史。&quot;</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>杨梅竹斜街位于北京市西城区大栅栏地区，东起煤市街，西至一尺大街，全长约496米。它是北京最有名的&quot;斜街&quot;之一，因清代曾聚集多家书局、书店而闻名，是民国时期北京的文化地标。如今经过更新改造，街区内既保留了老字号与传统风貌，又引入了众多设计工作室、文创店铺和特色咖啡馆，成为前门地区最有格调的慢游街区。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>开放时间</strong></td><td style="text-align:left;">全天开放</td></tr><tr><td style="text-align:left;"><strong>门票价格</strong></td><td style="text-align:left;">免费</td></tr><tr><td style="text-align:left;"><strong>建议游玩</strong></td><td style="text-align:left;">1-2小时</td></tr><tr><td style="text-align:left;"><strong>最佳季节</strong></td><td style="text-align:left;">春秋季</td></tr><tr><td style="text-align:left;"><strong>交通方式</strong></td><td style="text-align:left;">地铁7号线虎坊桥站或8号线珠市口站</td></tr><tr><td style="text-align:left;"><strong>地址</strong></td><td style="text-align:left;">北京市西城区杨梅竹斜街</td></tr></tbody></table><h2 id="历史沿革" tabindex="-1">历史沿革 <a class="header-anchor" href="#历史沿革" aria-label="Permalink to &quot;历史沿革&quot;">​</a></h2><h3 id="名字由来" tabindex="-1">名字由来 <a class="header-anchor" href="#名字由来" aria-label="Permalink to &quot;名字由来&quot;">​</a></h3><p>杨梅竹斜街的名字始于明代，相传因胡同内种植杨梅树而得名。</p><h3 id="书业一条街" tabindex="-1">书业一条街 <a class="header-anchor" href="#书业一条街" aria-label="Permalink to &quot;书业一条街&quot;">​</a></h3><p>清末民初，杨梅竹斜街聚集了商务印书馆、中华书局等众多书局与出版机构，是当时北京的出版文化中心，鲁迅、沈从文等文人常在此出入。</p><h3 id="当代更新" tabindex="-1">当代更新 <a class="header-anchor" href="#当代更新" aria-label="Permalink to &quot;当代更新&quot;">​</a></h3><p>2010年前后，大栅栏地区启动更新改造，设计师与艺术家入驻，老街焕发新生，成为&quot;北京式慢生活&quot;的样板街区。</p><h2 id="街区特色" tabindex="-1">街区特色 <a class="header-anchor" href="#街区特色" aria-label="Permalink to &quot;街区特色&quot;">​</a></h2><h3 id="老字号与书店传统" tabindex="-1">老字号与书店传统 <a class="header-anchor" href="#老字号与书店传统" aria-label="Permalink to &quot;老字号与书店传统&quot;">​</a></h3><p>街区内仍保留着济安斋、东昇平等老字号，也有许多主打设计类书籍的特色书店，延续着&quot;书街&quot;的文脉。</p><h3 id="设计工作室与文创店" tabindex="-1">设计工作室与文创店 <a class="header-anchor" href="#设计工作室与文创店" aria-label="Permalink to &quot;设计工作室与文创店&quot;">​</a></h3><p>众多建筑师、设计师的工作室和原创品牌店隐匿其间，展览、装置艺术不时出现，边走边逛常有惊喜。</p><h3 id="胡同咖啡馆" tabindex="-1">胡同咖啡馆 <a class="header-anchor" href="#胡同咖啡馆" aria-label="Permalink to &quot;胡同咖啡馆&quot;">​</a></h3><p>改造后的四合院与临街小屋变身为风格各异的咖啡馆、茶馆，适合歇脚闲聊。</p><h2 id="游览攻略" tabindex="-1">游览攻略 <a class="header-anchor" href="#游览攻略" aria-label="Permalink to &quot;游览攻略&quot;">​</a></h2><h3 id="推荐路线" tabindex="-1">推荐路线 <a class="header-anchor" href="#推荐路线" aria-label="Permalink to &quot;推荐路线&quot;">​</a></h3><p><strong>半日路线</strong>：</p><p>杨梅竹斜街东口 → 老字号店铺 → 设计工作室 → 咖啡馆 → 西口一尺大街 → 琉璃厂</p><h3 id="实用贴士" tabindex="-1">实用贴士 <a class="header-anchor" href="#实用贴士" aria-label="Permalink to &quot;实用贴士&quot;">​</a></h3><ol><li><strong>搭配</strong>：与琉璃厂文化街、前门大街、大栅栏连成一片，适合串联游览</li><li><strong>错峰</strong>：游客较前门大街少，午后光影最佳</li><li><strong>拍照</strong>：红砖墙、老招牌和民国风格的门脸是绝佳取景点</li><li><strong>注意</strong>：街区内多为居民生活区，请保持安静、勿打扰住户</li></ol><h3 id="交通方式" tabindex="-1">交通方式 <a class="header-anchor" href="#交通方式" aria-label="Permalink to &quot;交通方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">路线</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>地铁</strong></td><td style="text-align:left;">7号线虎坊桥站，或8号线珠市口站</td></tr><tr><td style="text-align:left;"><strong>公交</strong></td><td style="text-align:left;">前门西大街附近公交站步行可达</td></tr><tr><td style="text-align:left;"><strong>打车</strong></td><td style="text-align:left;">定位&quot;杨梅竹斜街&quot;即可</td></tr></tbody></table><h2 id="周边景点" tabindex="-1">周边景点 <a class="header-anchor" href="#周边景点" aria-label="Permalink to &quot;周边景点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">景点</th><th style="text-align:center;">距离</th><th style="text-align:left;">特色</th></tr></thead><tbody><tr><td style="text-align:left;">琉璃厂文化街</td><td style="text-align:center;">步行10分钟</td><td style="text-align:left;">文房四宝与古玩</td></tr><tr><td style="text-align:left;">大栅栏</td><td style="text-align:center;">步行10分钟</td><td style="text-align:left;">老字号商业街</td></tr><tr><td style="text-align:left;">前门大街</td><td style="text-align:center;">步行15分钟</td><td style="text-align:left;">正阳门城楼</td></tr><tr><td style="text-align:left;">天安门广场</td><td style="text-align:center;">步行20分钟</td><td style="text-align:left;">城市中心地标</td></tr></tbody></table><h2 id="文化意义" tabindex="-1">文化意义 <a class="header-anchor" href="#文化意义" aria-label="Permalink to &quot;文化意义&quot;">​</a></h2><p>杨梅竹斜街是北京旧城更新中&quot;原住民共生&quot;的代表案例。它没有大拆大建，而是在保留生活肌理的前提下引入新业态，让老街区既有烟火气，也有设计感。</p><hr><p><strong>📍 地址</strong>：北京市西城区杨梅竹斜街 <strong>🚇 地铁</strong>：7号线虎坊桥站 / 8号线珠市口站</p><p><strong>💡 Tips</strong>：杨梅竹斜街是拍照和漫步的好地方，建议留出整段时间去慢慢感受，别急着赶路。</p>',36)])])}const f=e(n,[["render",o]]);export{u as __pageData,f as default};
